-- =============================================================================
-- UPAY AI FINANCIAL INTELLIGENCE PLATFORM — SUPABASE POSTGRESQL SCHEMA & SEED
-- Database: PostgreSQL 15+ (Supabase Cloud)
-- Generated for DIU CPC x upay AI Hackathon 2026
-- =============================================================================

-- Enable UUID extension if needed
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Drop existing tables in reverse dependency order
DROP TABLE IF EXISTS notifications CASCADE;
DROP TABLE IF EXISTS ai_activity_logs CASCADE;
DROP TABLE IF EXISTS voice_transcripts CASCADE;
DROP TABLE IF EXISTS voice_calls CASCADE;
DROP TABLE IF EXISTS credit_recommendations CASCADE;
DROP TABLE IF EXISTS case_events CASCADE;
DROP TABLE IF EXISTS cases CASCADE;
DROP TABLE IF EXISTS complaints CASCADE;
DROP TABLE IF EXISTS card_transactions CASCADE;
DROP TABLE IF EXISTS cards CASCADE;
DROP TABLE IF EXISTS customers CASCADE;

-- -----------------------------------------------------------------------------
-- 1. CUSTOMERS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS customers (
    customer_id VARCHAR(50) PRIMARY KEY,
    display_name VARCHAR(100) NOT NULL,
    phone_masked VARCHAR(20) NOT NULL,
    raw_phone VARCHAR(20) NOT NULL,
    dob VARCHAR(20) NOT NULL,
    father_name_demo VARCHAR(100) NOT NULL,
    account_number VARCHAR(30) NOT NULL,
    account_balance_bdt DOUBLE PRECISION DEFAULT 25450.00,
    cash_reward_bdt DOUBLE PRECISION DEFAULT 150.00,
    status VARCHAR(20) DEFAULT 'ACTIVE',
    pin_hash VARCHAR(100) DEFAULT '1234',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- -----------------------------------------------------------------------------
-- 2. SMART CARDS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cards (
    card_id VARCHAR(50) PRIMARY KEY,
    customer_id VARCHAR(50) REFERENCES customers(customer_id) ON DELETE CASCADE,
    card_type VARCHAR(50) DEFAULT 'DUAL_CURRENCY',
    card_title VARCHAR(100) DEFAULT 'Upay Global Smart Card',
    card_number_masked VARCHAR(30) DEFAULT '•••• •••• •••• 4821',
    card_number_full VARCHAR(30) DEFAULT '4532 8912 6543 4821',
    expiry_date VARCHAR(10) DEFAULT '12/29',
    cvv VARCHAR(5) DEFAULT '123',
    status VARCHAR(20) DEFAULT 'ACTIVE',
    card_enabled BOOLEAN DEFAULT TRUE,
    online_enabled BOOLEAN DEFAULT TRUE,
    international_enabled BOOLEAN DEFAULT TRUE,
    nfc_enabled BOOLEAN DEFAULT TRUE,
    endorsement_usd DOUBLE PRECISION DEFAULT 1200.0,
    used_usd DOUBLE PRECISION DEFAULT 340.0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- -----------------------------------------------------------------------------
-- 3. CARD TRANSACTIONS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS card_transactions (
    transaction_id VARCHAR(50) PRIMARY KEY,
    card_id VARCHAR(50) REFERENCES cards(card_id) ON DELETE CASCADE,
    customer_id VARCHAR(50) NOT NULL,
    amount_usd DOUBLE PRECISION NOT NULL,
    amount_bdt DOUBLE PRECISION DEFAULT 0.0,
    merchant_name VARCHAR(100) NOT NULL,
    channel VARCHAR(30) DEFAULT 'ONLINE',
    country VARCHAR(10) DEFAULT 'US',
    risk_score INTEGER DEFAULT 15,
    risk_level VARCHAR(20) DEFAULT 'LOW',
    decision VARCHAR(20) DEFAULT 'ALLOW',
    reasons TEXT DEFAULT '[]',
    risk_breakdown TEXT DEFAULT '{}',
    fraud_score INTEGER DEFAULT 0,
    anomaly_score INTEGER DEFAULT 0,
    device_id VARCHAR(50) DEFAULT 'DEV-APP-01',
    recommended_action VARCHAR(100) DEFAULT 'ALLOW',
    model_version VARCHAR(80) DEFAULT 'fraud-xgb-1.0.0+anomaly-iforest-1.0.0',
    status VARCHAR(30) DEFAULT 'APPROVED',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- -----------------------------------------------------------------------------
-- 4. COMPLAINTS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS complaints (
    complaint_id VARCHAR(50) PRIMARY KEY,
    customer_id VARCHAR(50) NOT NULL,
    complaint_text TEXT NOT NULL,
    category VARCHAR(50) NOT NULL,
    priority VARCHAR(20) DEFAULT 'MEDIUM',
    channel VARCHAR(20) DEFAULT 'IN_APP',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- -----------------------------------------------------------------------------
-- 5. CASES TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cases (
    case_id VARCHAR(50) PRIMARY KEY,
    complaint_id VARCHAR(50) NOT NULL,
    customer_id VARCHAR(50) NOT NULL,
    case_title VARCHAR(150) NOT NULL,
    category VARCHAR(50) NOT NULL,
    priority VARCHAR(20) DEFAULT 'MEDIUM',
    status VARCHAR(30) DEFAULT 'INVESTIGATING',
    progress_percent INTEGER DEFAULT 50,
    assigned_team VARCHAR(80) DEFAULT 'TRANSACTION_OPERATIONS',
    assigned_agent VARCHAR(50) DEFAULT 'AGT-408',
    ai_summary TEXT DEFAULT '',
    escalation_level INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    resolved_at TIMESTAMP WITH TIME ZONE
);

-- -----------------------------------------------------------------------------
-- 6. CASE EVENTS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS case_events (
    event_id VARCHAR(50) PRIMARY KEY,
    case_id VARCHAR(50) REFERENCES cases(case_id) ON DELETE CASCADE,
    timestamp TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    event_type VARCHAR(50) NOT NULL,
    description TEXT NOT NULL,
    actor_type VARCHAR(30) DEFAULT 'SYSTEM',
    actor_id VARCHAR(50) DEFAULT 'SYS-AUTO'
);

-- -----------------------------------------------------------------------------
-- 7. CREDIT RECOMMENDATIONS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS credit_recommendations (
    recommendation_id VARCHAR(50) PRIMARY KEY,
    customer_id VARCHAR(50) NOT NULL,
    readiness_score INTEGER DEFAULT 86,
    risk_probability DOUBLE PRECISION DEFAULT 0.14,
    risk_category VARCHAR(20) DEFAULT 'LOW',
    suggested_limit_range_bdt VARCHAR(50) DEFAULT 'BDT 20,000 - BDT 30,000',
    recommendation VARCHAR(50) DEFAULT 'RECOMMENDED_FOR_PARTNER_REVIEW',
    positive_factors TEXT DEFAULT '[]',
    negative_factors TEXT DEFAULT '[]',
    review_requested BOOLEAN DEFAULT FALSE,
    review_requested_at TIMESTAMP WITH TIME ZONE,
    review_status VARCHAR(50) DEFAULT 'NOT_REQUESTED',
    model_version VARCHAR(50) DEFAULT 'credit-xgb-1.0.0',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- -----------------------------------------------------------------------------
-- 8. VOICE CALLS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS voice_calls (
    call_id VARCHAR(50) PRIMARY KEY,
    customer_id VARCHAR(50),
    phone_number VARCHAR(20) DEFAULT '01771449164',
    verified BOOLEAN DEFAULT FALSE,
    intent VARCHAR(50) DEFAULT 'INQUIRY',
    status VARCHAR(30) DEFAULT 'ACTIVE',
    escalated BOOLEAN DEFAULT FALSE,
    escalation_team VARCHAR(80),
    call_duration_seconds INTEGER DEFAULT 0,
    summary TEXT DEFAULT '',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- -----------------------------------------------------------------------------
-- 9. VOICE TRANSCRIPTS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS voice_transcripts (
    transcript_id VARCHAR(50) PRIMARY KEY,
    call_id VARCHAR(50) REFERENCES voice_calls(call_id) ON DELETE CASCADE,
    speaker VARCHAR(20) NOT NULL,
    text TEXT NOT NULL,
    timestamp TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- -----------------------------------------------------------------------------
-- 10. AI ACTIVITY LOGS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ai_activity_logs (
    ai_log_id VARCHAR(50) PRIMARY KEY,
    correlation_id VARCHAR(50) NOT NULL,
    customer_id VARCHAR(50),
    component VARCHAR(50) NOT NULL,
    action VARCHAR(80) NOT NULL,
    tool_name VARCHAR(80) DEFAULT '',
    model_or_provider VARCHAR(50) DEFAULT '',
    model_version VARCHAR(50) DEFAULT '',
    result_status VARCHAR(30) DEFAULT 'SUCCESS',
    latency_ms DOUBLE PRECISION DEFAULT 15.0,
    details TEXT DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- -----------------------------------------------------------------------------
-- 11. NOTIFICATIONS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS notifications (
    notification_id VARCHAR(50) PRIMARY KEY,
    customer_id VARCHAR(50) NOT NULL,
    title VARCHAR(150) NOT NULL,
    message TEXT NOT NULL,
    type VARCHAR(30) DEFAULT 'INFO',
    read BOOLEAN DEFAULT FALSE,
    action_url VARCHAR(100) DEFAULT '',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);


